def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    rows = len(grid)
    for i in range(rows):
        if i % 2 == 0:
            # Traverse left to right
            result.extend(grid[i][j] for j in range(len(grid[i])) if j % 2 == 0)
        else:
            # Traverse right to left
            result.extend(grid[i][j] for j in range(len(grid[i])-1, -1, -1) if j % 2 == 1)
    return result

def findValidPair(s: str) -> str:
    # Count occurrences of each digit
    count = {str(i): 0 for i in range(1, 10)}
    for char in s:
        count[char] += 1

    # Traverse the string to find valid pairs
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a != b and count[a] == int(a) and count[b] == int(b):
            return a + b

    return ""

