def sumOfGoodNumbers(nums: List[int], k: int) -> int:
    total_sum = 0
    n = len(nums)
    for i in range(n):
        is_good = True
        if i - k >= 0:
            is_good = is_good and (nums[i] > nums[i - k])
        if i + k < n:
            is_good = is_good and (nums[i] > nums[i + k])
        if is_good:
            total_sum += nums[i]
    return total_sum

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if substring == substring[0] * k:
            before_is_different = i == 0 or s[i - 1] != substring[0]
            after_is_different = i + k == n or s[i + k] != substring[0]
            if before_is_different and after_is_different:
                return True
    return False

def hasSameDigits(s: str) -> bool:
    while len(s) > 2:
        s = ''.join(str((int(s[i]) + int(s[i + 1])) % 10) for i in range(len(s) - 1))
    return s[0] == s[1]

