def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict

    count = defaultdict(int)
    n = len(nums)

    # Count occurrences of each integer in every subarray of size k
    for i in range(n - k + 1):
        seen = set()
        for j in range(k):
            seen.add(nums[i + j])
        for num in seen:
            count[num] += 1

    # Find the largest integer that appears in exactly one subarray
    largest = -1
    for num, c in count.items():
        if c == 1:
            largest = max(largest, num)

    return largest

def maxContainers(n: int, w: int, maxWeight: int) -> int:
    total_cells = n * n
    max_by_weight = maxWeight // w
    return min(total_cells, max_by_weight)

