def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Create adjacency list with weights
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Function to check if we can reach node 0 with max edge weight allowed
    def can_reach_zero(max_weight):
        out_degree = [0] * n
        visited = [False] * n
        queue = []

        # BFS to check reachable nodes with the current max weight
        for start_node in range(n):
            if not visited[start_node]:
                stack = [start_node]
                while stack:
                    current = stack.pop()
                    if visited[current]:
                        continue
                    visited[current] = True
                    for neighbor, weight in graph[current]:
                        if weight <= max_weight:
                            if out_degree[current] < threshold:
                                out_degree[current] += 1
                                if not visited[neighbor]:
                                    stack.append(neighbor)

        # After processing, return whether node 0 is reachable
        return visited[0]  # Check if node 0 is reachable

    # Binary search for the minimum maximum weight
    left, right = 1, 10**6
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if can_reach_zero(mid):
            result = mid
            right = mid - 1  # Try for a smaller max weight
        else:
            left = mid + 1  # Increase max weight

    return result

